using Microsoft.EntityFrameworkCore;using TechStore.App.Data;using TechStore.App.DTOs;using TechStore.App.Enums;using TechStore.App.Models;using TechStore.App.Services;
namespace TechStore.App.Views;
public partial class DashboardForm:Form{public DashboardForm(){InitializeComponent();Shown+=async(_,_)=>{await using var db=new TechStoreDbContext();var today=DateTime.Today;summary.Text=$"Ventas del día: {await db.Sales.CountAsync(x=>x.Date>=today&&!x.IsCancelled)}     Facturación: {(await db.Sales.Where(x=>x.Date>=today&&!x.IsCancelled).SumAsync(x=>(decimal?)x.Total)??0):C}\nProductos activos: {await db.Products.CountAsync(x=>x.IsActive)}     Clientes activos: {await db.Customers.CountAsync(x=>x.IsActive)}     Clientes con deuda: {await db.Customers.CountAsync(x=>x.CurrentAccountBalance>0)}";grid.DataSource=await db.Inventories.AsNoTracking().Where(x=>x.Stock<=x.MinimumStock).Select(x=>new{x.Product.Code,Producto=x.Product.Name,Sucursal=x.Branch.Name,x.Stock,x.MinimumStock}).ToListAsync();};}}
public partial class InventoryForm:Form{public InventoryForm(){InitializeComponent();Shown+=async(_,_)=>await LoadData();}async Task LoadData(){await using var db=new TechStoreDbContext();grid.DataSource=await db.Inventories.AsNoTracking().Select(x=>new{x.Id,Codigo=x.Product.Code,Producto=x.Product.Name,Sucursal=x.Branch.Name,x.Stock,x.MinimumStock}).ToListAsync();foreach(DataGridViewRow r in grid.Rows)if(Convert.ToInt32(r.Cells["Stock"].Value)<=Convert.ToInt32(r.Cells["MinimumStock"].Value))r.DefaultCellStyle.BackColor=Color.MistyRose;}async void Adjust(object?s,EventArgs e){if(grid.CurrentRow==null)return;await using var db=new TechStoreDbContext();var id=(int)grid.CurrentRow.Cells["Id"].Value;var inv=await db.Inventories.FindAsync(id);if(inv==null)return;var value=(int)amount.Value;if(inv.Stock+value<0){MessageBox.Show("El stock no puede quedar negativo.");return;}inv.Stock+=value;await db.SaveChangesAsync();await LoadData();}}
public partial class AccountPaymentForm:Form{public AccountPaymentForm(){InitializeComponent();Shown+=async(_,_)=>await LoadCustomers();}async Task LoadCustomers(){await using var db=new TechStoreDbContext();customers.DataSource=await db.Customers.AsNoTracking().Where(x=>x.IsActive).ToListAsync();customers.DisplayMember="BusinessName";customers.ValueMember="Id";}async void Pay(object?s,EventArgs e){try{await using var db=new TechStoreDbContext();await new AccountService(db).RegisterPaymentAsync((int)customers.SelectedValue,amount.Value,description.Text);MessageBox.Show("Pago registrado correctamente.");}catch(Exception ex){MessageBox.Show(ex.Message,"Validación");}}}
public partial class SaleForm:Form{readonly List<SaleLineRequest> lines=[];readonly Dictionary<int,string> productNames=[];public SaleForm(){InitializeComponent();Shown+=async(_,_)=>await LoadCombos();payment.SelectedValueChanged+=(_,_)=>{var cc=payment.SelectedItem is PaymentMethod.CuentaCorriente;status.SelectedItem=cc?PaymentStatus.Pendiente:PaymentStatus.Pagado;status.Enabled=false;};}async Task LoadCombos(){await using var db=new TechStoreDbContext();customer.DataSource=await db.Customers.AsNoTracking().Where(x=>x.IsActive).OrderBy(x=>x.BusinessName).ToListAsync();customer.DisplayMember="BusinessName";customer.ValueMember="Id";branch.DataSource=await db.Branches.AsNoTracking().Where(x=>x.IsActive).OrderBy(x=>x.Name).ToListAsync();branch.DisplayMember="Name";branch.ValueMember="Id";seller.DataSource=await db.Sellers.AsNoTracking().Where(x=>x.IsActive).OrderBy(x=>x.Name).ToListAsync();seller.DisplayMember="Name";seller.ValueMember="Id";var products=await db.Products.AsNoTracking().Where(x=>x.IsActive).OrderBy(x=>x.Name).ToListAsync();foreach(var p in products)productNames[p.Id]=$"{p.Code} - {p.Name}";product.DataSource=products;product.DisplayMember="Name";product.ValueMember="Id";}void AddLine(object?s,EventArgs e){if(product.SelectedValue is not int id)return;var existing=lines.FindIndex(x=>x.ProductId==id);if(existing>=0)lines[existing]=lines[existing] with{Quantity=lines[existing].Quantity+(int)quantity.Value};else lines.Add(new(id,(int)quantity.Value));grid.DataSource=lines.Select(x=>new{Producto=productNames.GetValueOrDefault(x.ProductId,x.ProductId.ToString()),x.Quantity}).ToList();}async void Confirm(object?s,EventArgs e){try{if(customer.SelectedValue is not int customerId||branch.SelectedValue is not int branchId||seller.SelectedValue is not int sellerId)throw new InvalidOperationException("Seleccione cliente, sucursal y vendedor.");await using var db=new TechStoreDbContext();var sale=await new SaleService(db).CreateAsync(new(customerId,branchId,sellerId,DateTime.Now,(PaymentMethod)payment.SelectedItem!,(PaymentStatus)status.SelectedItem!,notes.Text,lines));MessageBox.Show($"Venta {sale.InvoiceNumber} registrada. Total: {sale.Total:C}");new InvoiceForm(sale.Id).ShowDialog(this);lines.Clear();grid.DataSource=null;}catch(Exception ex){MessageBox.Show(ex.Message,"No se pudo registrar");}}}
public partial class SalesHistoryForm:Form{public SalesHistoryForm(){InitializeComponent();Shown+=async(_,_)=>await LoadData();}async Task LoadData(){await using var db=new TechStoreDbContext();grid.DataSource=await db.Sales.AsNoTracking().Select(x=>new{x.Id,x.InvoiceNumber,x.Date,Cliente=x.Customer.BusinessName,Sucursal=x.Branch.Name,Vendedor=x.Seller.Name,x.Total,x.PaymentMethod,x.IsCancelled}).ToListAsync();}async void Cancel(object?s,EventArgs e){if(grid.CurrentRow==null||MessageBox.Show("¿Confirma la anulación?","Anular",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;try{await using var db=new TechStoreDbContext();await new SaleService(db).CancelAsync((int)grid.CurrentRow.Cells["Id"].Value);await LoadData();}catch(Exception ex){MessageBox.Show(ex.Message);}}}
public partial class ReportsForm:Form{public ReportsForm(){InitializeComponent();Shown+=async(_,_)=>await Run();}async Task Run(){await using var db=new TechStoreDbContext();sales.DataSource=await db.Sales.AsNoTracking().Where(x=>!x.IsCancelled).GroupBy(x=>x.Branch.Name).Select(x=>new{Sucursal=x.Key,Cantidad=x.Count(),Total=x.Sum(y=>y.Total)}).ToListAsync();products.DataSource=await db.SaleItems.AsNoTracking().Where(x=>!x.Sale.IsCancelled).GroupBy(x=>x.Product.Name).Select(x=>new{Producto=x.Key,Cantidad=x.Sum(y=>y.Quantity),Importe=x.Sum(y=>y.Subtotal)}).OrderByDescending(x=>x.Cantidad).ToListAsync();accounts.DataSource=await db.Customers.AsNoTracking().Where(x=>x.CurrentAccountBalance>0).Select(x=>new{Cliente=x.BusinessName,Tipo=x.CustomerType,Saldo=x.CurrentAccountBalance}).ToListAsync();}}
public partial class InvoiceForm:Form{readonly int id;public InvoiceForm(int id){this.id=id;InitializeComponent();Shown+=async(_,_)=>await LoadInvoice();}async Task LoadInvoice(){await using var db=new TechStoreDbContext();var s=await db.Sales.AsNoTracking().Include(x=>x.Customer).Include(x=>x.Branch).Include(x=>x.Seller).Include(x=>x.Items).ThenInclude(x=>x.Product).SingleAsync(x=>x.Id==id);text.Text=$"TECHSTORE S.A.\r\nFactura: {s.InvoiceNumber}    Fecha: {s.Date:g}\r\nSucursal: {s.Branch.Name}    Vendedor: {s.Seller.Name}\r\nCliente: {s.Customer.BusinessName} ({s.Customer.CustomerType})\r\n\r\n"+string.Join("\r\n",s.Items.Select(x=>$"{x.Product.Code}  {x.Product.Name}  {x.Quantity} x {x.UnitPrice:C} = {x.Subtotal:C}"))+$"\r\n\r\nSubtotal: {s.Subtotal:C}\r\nDescuento: {s.DiscountAmount:C}\r\nTOTAL: {s.Total:C}\r\nPago: {s.PaymentMethod} - {s.PaymentStatus}\r\nObservaciones: {s.Notes}";}void Preview(object?s,EventArgs e){document.PrintPage+=(_,a)=>a.Graphics.DrawString(text.Text,text.Font,Brushes.Black,a.MarginBounds);using var d=new PrintPreviewDialog{Document=document};d.ShowDialog(this);}void Print(object?s,EventArgs e){using var d=new PrintDialog{Document=document};if(d.ShowDialog(this)==DialogResult.OK)document.Print();}}
